    private void seed(JdbcTemplate db,String password){var day=LocalDate.now(com.adc.domain.shared.BusinessTime.ZONE).minusDays(1);var at=day.atTime(9,0).atZone(com.adc.domain.shared.BusinessTime.ZONE).withZoneSameInstant(ZoneOffset.UTC).toLocalDateTime();for(String subject:List.of(USER,TARGET,PATIENT))db.update("INSERT INTO adc_identity.Subject VALUES (?,?,true,?,NULL)",subject,subject.equals(PATIENT)?"PATIENT":"STAFF",at.minusDays(2));for(String subject:List.of(USER,TARGET))db.update("INSERT INTO adc_identity.StaffAccount VALUES (?,?,?,NULL,?,false,?,'owned verified staff')",subject,subject.equals(USER)?"owned-matrix-no-grants":"owned-matrix-target","Owned staff",password,at.minusDays(2));db.update("INSERT INTO adc_business.Clinic VALUES (1,'MATRIX-C1','Owned clinic',NULL,'000',NULL,NULL,true,?)",at.minusDays(2));db.update("INSERT INTO adc_business.Dentist (dentist_id,employee_number,full_name,date_of_birth,home_address,phone,email,hire_date,is_active,created_at,termination_date) VALUES (1,'MATRIX-D1','Owned dentist','1980-01-01',NULL,'000',NULL,'2020-01-01',true,?,NULL)",at.minusDays(2));db.update("INSERT INTO adc_business.DentistClinicAssignment VALUES (1,1,1,'2020-01-01',NULL,NULL,true)");db.update("INSERT INTO adc_business.Patient VALUES (1,'MATRIX-P1','PRIVATE-MATRIX-CANARY','1990-01-01','PRIVATE-MATRIX-CANARY','000',NULL,'Fixture','000',?,?,'RECORDED')",at.minusDays(2),at.minusDays(2));db.update("INSERT INTO adc_business.Allergy VALUES (1,'Owned allergy',NULL,true)");db.update("INSERT INTO adc_business.PatientAllergy VALUES (1,1,?,'MILD',NULL,false,JSON_ARRAY(),?)",at.minusDays(2),at.minusDays(2));db.update("INSERT INTO adc_business.Qualification VALUES (1,'Owned qualification',NULL,true)");db.update("INSERT INTO adc_business.Treatment VALUES (1,'MATRIX-T1','Owned treatment',NULL,10.00,true)");db.update("INSERT INTO adc_business.DentistSchedule VALUES (1,1,1,?,'09:00:00','10:00:00',20,'NORMAL',NULL,?)",day,at.minusDays(1));db.update("INSERT INTO adc_business.Appointment (appointment_id,patient_id,clinic_id,dentist_id,schedule_id,scheduled_at,status,created_at,updated_at,attended_at,completed_at) VALUES (1,1,1,1,1,?,'INVOICED',?,?,?,?)",at,at.minusDays(1),at.plusMinutes(10),at,at.plusMinutes(10));db.update("INSERT INTO adc_business.AppliedTreatment VALUES (1,1,1,1,1.00,10.00,10.00,?)",at.plusMinutes(5));db.update("INSERT INTO adc_business.Invoice VALUES (1,'MATRIX-I1',1,?,10.00,'ISSUED',?)",at.plusMinutes(10),at.plusMinutes(10));db.update("INSERT INTO adc_business.InvoiceItem VALUES (1,1,1,1,'Owned treatment',1.00,10.00,10.00)");db.update("INSERT INTO adc_identity.AccessGrant VALUES (?,?,'RECEPTION',?,?,NULL,NULL,NULL,'owned fixture',?)",GRANT,TARGET,USER,at.minusDays(1),at.minusDays(1));db.update("INSERT INTO adc_identity.GrantClinicScope VALUES (?,1)",GRANT);db.update("INSERT INTO adc_identity.BindingRequest VALUES (?,?, 'MATRIX-P1','1990-01-01',1,NULL,'PENDING',?,NULL,NULL,NULL,NULL)",REQUEST,PATIENT,at);db.update("INSERT INTO adc_identity.CurrentPatientBinding VALUES (?,1,?,?,?)",PATIENT,TARGET,at,"owned verified binding");db.update("INSERT INTO adc_business.CostEntry VALUES (1,1,1,NULL,NULL,'MEDICAL_SUPPLY',10.00,?,NULL,'MATRIX-COST','owned',?,'owned verified operator',NULL)",at,at);String input="{\"input\":{\"rule\":\"R1\",\"start\":\"2026-07-01\",\"end\":\"2026-10-01\",\"cutoff\":\"2026-11-01T00:00:00Z\",\"clinics\":[\"1\"],\"personnel\":[],\"assignments\":[],\"schedules\":[],\"revenue\":[],\"costs\":[],\"closures\":[],\"personnelReference\":null,\"preparer\":null},\"incomplete_reasons\":[\"MISSING_PREPARATION\"],\"allocations\":[]}";db.update("INSERT INTO adc_business.QuarterlyPerformance VALUES (1,1,'2026-07-01','2026-10-01',NULL,NULL,NULL,NULL,0.1000,NULL,'INCOMPLETE',NULL,1,?,?,NULL)",input,"0".repeat(64));}
